engine.getRank:
function getRank(trophyCount) {
  var n = Number(trophyCount) || 0;
  if (n >= 100) return "Grandmaster";
  if (n >= 80)  return "Executive";
  if (n >= 60)  return "Architect";
  if (n >= 40)  return "Strategist";
  if (n >= 20)  return "Specialist";
  return "Novice";
}

// Returns { rank, currentIdx, nextRank, nextIdx, isMax,
//           currentThreshold, nextThreshold, trophiesNeeded,
//           progressToNext }. FROM v2 showTrophyGallery line 13-36.

engine.computeRankProgress:
function computeRankProgress(trophyCount) {
  var n = Number(trophyCount) || 0;
  var rankThresholds = [
    { name: "Novice",      min: 0 },
    { name: "Specialist",  min: 20 },
    { name: "Strategist",  min: 40 },
    { name: "Architect",   min: 60 },
    { name: "Executive",   min: 80 },
    { name: "Grandmaster", min: 100 },
  ];
  var currentIdx = 0;
  for (var i = rankThresholds.length - 1; i >= 0; i--) {
    if (n >= rankThresholds[i].min) { currentIdx = i; break; }
  }
  var isMax = currentIdx === rankThresholds.length - 1;
  var nextIdx = Math.min(currentIdx + 1, rankThresholds.length - 1);
  var currentThreshold = rankThresholds[currentIdx].min;
  var nextThreshold = rankThresholds[nextIdx].min;
  var trophiesNeeded = isMax ? 0 : nextThreshold - n;
  var progressToNext = isMax ? 100 :
    Math.min(100, Math.round(((n - currentThreshold) / (nextThreshold - currentThreshold)) * 100));
  return {
    rank: rankThresholds[currentIdx].name,
    currentIdx: currentIdx,
    nextRank: rankThresholds[nextIdx].name,
    nextIdx: nextIdx,
    isMax: isMax,
    currentThreshold: currentThreshold,
    nextThreshold: nextThreshold,
    trophiesNeeded: trophiesNeeded,
    progressToNext: progressToNext,
    rankThresholds: rankThresholds,
  };
}

// FROM v2 showTrophyGallery line 140-162. Trophies 0-69 always visible;
// 70+ unlock by rank tier.

engine.isTrophyVisible:
function isTrophyVisible(idx, rank) {
  var r = String(rank || "").toLowerCase();
  if (idx < 70) return true;
  if (idx >= 70 && idx <= 74) {
    return r === "specialist" || r === "strategist" || r === "architect" || r === "executive" || r === "grandmaster";
  }
  if (idx >= 75 && idx <= 79) {
    return r === "strategist" || r === "architect" || r === "executive" || r === "grandmaster";
  }
  if (idx >= 80 && idx <= 84) {
    return r === "architect" || r === "executive" || r === "grandmaster";
  }
  if (idx >= 85 && idx <= 94) {
    return r === "executive" || r === "grandmaster";
  }
  if (idx >= 95 && idx <= 103) return r === "grandmaster";
  return false;
}

// FROM v2 line 163-170. Which rank unlocks a trophy at this index?

engine.getRequiredRank:
function getRequiredRank(idx) {
  if (idx >= 70 && idx <= 74) return "Specialist";
  if (idx >= 75 && idx <= 79) return "Strategist";
  if (idx >= 80 && idx <= 84) return "Architect";
  if (idx >= 85 && idx <= 94) return "Executive";
  if (idx >= 95) return "Grandmaster";
  return "Specialist";
}

// Read user stats (v2-compat localStorage key). Returns the parsed
// blob or {unlockedTrophies:[]} as a safe default.

engine.readUserStats:
function readUserStats() {
  try {
    var raw = window.eli && window.eli.compat
      ? window.eli.compat.lsGet("eli_user_stats")
      : (typeof localStorage !== "undefined" ? localStorage.getItem("eli_user_stats") : null);
    if (!raw) return { unlockedTrophies: [] };
    var parsed = JSON.parse(raw);
    if (!parsed.unlockedTrophies) parsed.unlockedTrophies = [];
    return parsed;
  } catch (e) {
    return { unlockedTrophies: [] };
  }
}

// Engine entry — shapes everything view.js needs.

engine.analyze:
function analyze(input, providers) {
  var stats = readUserStats();
  var unlocked = stats.unlockedTrophies || [];
  var progress = computeRankProgress(unlocked.length);
  return Promise.resolve({
    unlocked: unlocked,
    rank: progress.rank,
    progress: progress,
    raw: stats,
    overview: unlocked.length + " trophy" + (unlocked.length === 1 ? "" : "ies") +
      " · " + progress.rank,
    provenance: {
      kernelVersion: (window.eli && window.eli.kernelVersion) || "v3",
      toolVersion: "v3.0",
      docHash: null,
      timestamp: Date.now(),
    },
  });
}

view._escTrophy:
function _escTrophy(s) {
  return String(s == null ? "" : s)
    .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
}

// Sidebar trophy chip. Appended to opts.mount. Returns the element so
// init can update count without re-rendering the whole sidebar.

view.renderSidebarBox:
function renderSidebarBox(opts) {
  var mount = opts.mount;
  if (!mount) return null;
  var count = Number(opts.count || 0);
  var onClick = opts.onClick || function () {};
  var box = document.createElement("div");
  box.className = "_eli3_sidebar_trophy";
  box.title = "Open trophy gallery — " + count + " unlocked of 104";
  box.innerHTML =
    '<span class="_eli3_sidebar_trophy_icon">🏆</span>' +
    '<span class="_eli3_sidebar_trophy_count">' + count + '/104</span>';
  box.onclick = onClick;
  mount.appendChild(box);
  return box;
}

// Full gallery overlay. Port of v2 showTrophyGallery (line 85-237) with
// the markup preserved but wiring routed through opts callbacks instead
// of window globals. opts:
//   { unlocked, rank, progress, trophies, onDetails, onClose, onReset }

view.renderGallery:
function renderGallery(opts) {
  var unlocked = opts.unlocked || [];
  var rank = String(opts.rank || "Novice");
  var progress = opts.progress || {};
  var trophies = opts.trophies || [];
  var onDetails = opts.onDetails || function () {};
  var onClose = opts.onClose || function () {};
  var onReset = opts.onReset || function () {};

  var existing = document.getElementById("_eli3_trophy_gallery_overlay");
  if (existing) existing.remove();

  var overlay = document.createElement("div");
  overlay.id = "_eli3_trophy_gallery_overlay";
  overlay.className = "_eli3_trophy_overlay";
  document.body.appendChild(overlay);

  var trophyCount = unlocked.length;
  var nextReward = (function () {
    var rewards = {
      Specialist: "Trophy Visibility 71-75",
      Strategist: "Trophy Visibility 76-84",
      Architect:  "Trophy Visibility 85-89",
      Executive:  "Trophy Visibility 90-104",
      Grandmaster: "Full Trophy Collection",
    };
    if (progress.isMax) return "All Perks Unlocked";
    return rewards[progress.nextRank] || "Exclusive Perks";
  })();

  var ranks = ["Novice", "Specialist", "Strategist", "Architect", "Executive", "Grandmaster"];
  var rankTrackHtml = ranks.map(function (r, idx) {
    var isCurrent = idx === progress.currentIdx;
    var isNext    = idx === progress.nextIdx && !progress.isMax;
    var isPast    = idx < progress.currentIdx;
    if (isPast) return '<span class="_eli3_trophy_rank _eli3_trophy_rank_past">✓ ' + r.toUpperCase() + '</span>';
    if (isCurrent) return '<span class="_eli3_trophy_rank _eli3_trophy_rank_current">● ' + r.toUpperCase() + '</span>';
    if (isNext) return '<span class="_eli3_trophy_rank _eli3_trophy_rank_next">→ ' + r.toUpperCase() + '</span>';
    return '<span class="_eli3_trophy_rank">' + r.toUpperCase() + '</span>';
  }).join('<span class="_eli3_trophy_rank_sep">›</span>');

  var progressLabel = progress.isMax
    ? '<span class="_eli3_trophy_max_label">🏆 MAX RANK ACHIEVED</span>'
    : '<span>' + trophyCount + ' / ' + progress.nextThreshold + ' Trophies</span>' +
      '<span class="_eli3_trophy_needed_label">' + progress.trophiesNeeded + ' more for <strong>' + _escTrophy(progress.nextRank) + '</strong></span>';

  // Determine visibility per trophy index.
  function _isVisible(idx) {
    var r = rank.toLowerCase();
    if (idx < 70) return true;
    if (idx >= 70 && idx <= 74) return r === "specialist" || r === "strategist" || r === "architect" || r === "executive" || r === "grandmaster";
    if (idx >= 75 && idx <= 79) return r === "strategist" || r === "architect" || r === "executive" || r === "grandmaster";
    if (idx >= 80 && idx <= 84) return r === "architect" || r === "executive" || r === "grandmaster";
    if (idx >= 85 && idx <= 94) return r === "executive" || r === "grandmaster";
    if (idx >= 95 && idx <= 103) return r === "grandmaster";
    return false;
  }
  function _reqRank(idx) {
    if (idx >= 70 && idx <= 74) return "Specialist";
    if (idx >= 75 && idx <= 79) return "Strategist";
    if (idx >= 80 && idx <= 84) return "Architect";
    if (idx >= 85 && idx <= 94) return "Executive";
    if (idx >= 95) return "Grandmaster";
    return "Specialist";
  }

  // Build card grid.
  var cardsHtml = "";
  var renderedCount = 0;
  for (var i = 0; i < trophies.length && renderedCount < 104; i++) {
    var t = trophies[i] || {};
    var trophyNum = renderedCount + 1;
    var isUnlocked = unlocked.indexOf(t.id) !== -1;
    if (!_isVisible(renderedCount) && !isUnlocked) {
      cardsHtml +=
        '<div class="_eli3_trophy_card _eli3_trophy_card_classified">' +
          '<div class="_eli3_trophy_card_num">#' + trophyNum + '</div>' +
          '<div class="_eli3_trophy_card_icon _eli3_trophy_icon_locked">🔒</div>' +
          '<div class="_eli3_trophy_card_label">Classified</div>' +
          '<div class="_eli3_trophy_card_hint">Viewable at <strong>' + _reqRank(renderedCount) + '</strong></div>' +
        '</div>';
      renderedCount++;
      continue;
    }
    var cls = isUnlocked ? "_eli3_trophy_card _eli3_trophy_card_unlocked" : "_eli3_trophy_card _eli3_trophy_card_locked";
    cardsHtml +=
      '<div class="' + cls + '" data-trophy-id="' + _escTrophy(t.id || "") + '">' +
        (isUnlocked ? '<div class="_eli3_trophy_card_badge">✓ UNLOCKED</div>' : "") +
        '<div class="_eli3_trophy_card_num">#' + trophyNum + '</div>' +
        '<div class="_eli3_trophy_card_icon">' + _escTrophy(t.icon || "🏆") + '</div>' +
        '<div class="_eli3_trophy_card_title">' + _escTrophy(t.title || t.id || "Trophy") + '</div>' +
        '<div class="_eli3_trophy_card_desc">' + _escTrophy(t.desc || "") + '</div>' +
      '</div>';
    renderedCount++;
  }
  while (renderedCount < 104) {
    var placeholderNum = renderedCount + 1;
    if (_isVisible(renderedCount)) {
      cardsHtml +=
        '<div class="_eli3_trophy_card _eli3_trophy_card_upcoming">' +
          '<div class="_eli3_trophy_card_num">#' + placeholderNum + '</div>' +
          '<div class="_eli3_trophy_card_icon">🎁</div>' +
          '<div class="_eli3_trophy_card_label">Upcoming</div>' +
          '<div class="_eli3_trophy_card_hint">Coming soon…</div>' +
        '</div>';
    } else {
      cardsHtml +=
        '<div class="_eli3_trophy_card _eli3_trophy_card_classified">' +
          '<div class="_eli3_trophy_card_num">#' + placeholderNum + '</div>' +
          '<div class="_eli3_trophy_card_icon _eli3_trophy_icon_locked">🔒</div>' +
          '<div class="_eli3_trophy_card_label">Classified</div>' +
          '<div class="_eli3_trophy_card_hint">Viewable at <strong>' + _reqRank(renderedCount) + '</strong></div>' +
        '</div>';
    }
    renderedCount++;
  }

  overlay.innerHTML =
    '<div class="_eli3_trophy_inner">' +
      '<button type="button" class="_eli3_trophy_back">← Back to Home</button>' +
      '<div class="_eli3_trophy_header">' +
        '<h1>🎖️ OPERATIONAL RANK</h1>' +
        '<div class="_eli3_trophy_subhead">Current standing within ELI</div>' +
      '</div>' +
      '<div class="_eli3_trophy_rankcard">' +
        '<div class="_eli3_trophy_rankcard_top">' +
          '<div>' +
            '<div class="_eli3_trophy_rankcard_eyebrow">Current Rank</div>' +
            '<div class="_eli3_trophy_rankcard_value">' + _escTrophy(rank) + '</div>' +
          '</div>' +
          '<div class="_eli3_trophy_rankcard_right">' +
            '<div class="_eli3_trophy_rankcard_eyebrow">' + (progress.isMax ? "Max Rank" : "Working Toward") + '</div>' +
            '<div class="_eli3_trophy_rankcard_next">' + (progress.isMax ? "🏆 Grandmaster" : "→ " + _escTrophy(progress.nextRank)) + '</div>' +
            '<div class="_eli3_trophy_rankcard_reward">' + (progress.isMax ? "" : "Reward: " + _escTrophy(nextReward)) + '</div>' +
          '</div>' +
        '</div>' +
        '<div class="_eli3_trophy_ranktrack">' + rankTrackHtml + '</div>' +
        '<div class="_eli3_trophy_progressbar">' +
          '<div class="_eli3_trophy_progressbar_fill" style="width:' + progress.progressToNext + '%;' + (progress.isMax ? "background:linear-gradient(90deg,#3b82f6,#34d399);" : "") + '"></div>' +
        '</div>' +
        '<div class="_eli3_trophy_progresslabel">' + progressLabel + '</div>' +
      '</div>' +
      '<div class="_eli3_trophy_vault_header">' +
        '<div>' +
          '<h1>🏆 TROPHY VAULT</h1>' +
          '<div class="_eli3_trophy_subhead">Collected Achievements &amp; Milestones</div>' +
        '</div>' +
        '<div class="_eli3_trophy_vault_count">🏆 ' + trophyCount + ' <span>/ 104</span></div>' +
      '</div>' +
      '<div class="_eli3_trophy_grid">' + cardsHtml + '</div>' +
      '<div class="_eli3_trophy_reset_row">' +
        '<button type="button" class="_eli3_trophy_reset_btn">🔒 Reset Trophies &amp; User Stats</button>' +
      '</div>' +
    '</div>';

  // Wire close.
  var back = overlay.querySelector("._eli3_trophy_back");
  if (back) back.onclick = function () {
    overlay.classList.add("_eli3_trophy_overlay_closing");
    setTimeout(function () { if (overlay.parentNode) overlay.remove(); }, 240);
    onClose();
  };
  // Wire card clicks (only unlocked / non-classified are interactive).
  Array.prototype.forEach.call(overlay.querySelectorAll("[data-trophy-id]"), function (card) {
    var id = card.getAttribute("data-trophy-id");
    if (!id) return;
    card.onclick = function () { onDetails(id); };
  });
  // Wire reset button.
  var resetBtn = overlay.querySelector("._eli3_trophy_reset_btn");
  if (resetBtn) resetBtn.onclick = function () { onReset(); };

  // Fade in.
  requestAnimationFrame(function () {
    requestAnimationFrame(function () { overlay.classList.add("_eli3_trophy_overlay_open"); });
  });

  return {
    close: function () {
      overlay.classList.add("_eli3_trophy_overlay_closing");
      setTimeout(function () { if (overlay.parentNode) overlay.remove(); }, 240);
    },
  };
}

// Trophy details modal — light dialog with the trophy's icon + title +
// desc + unlock date. Used when the user clicks a card in the gallery.

view.renderTrophyDetails:
function renderTrophyDetails(opts) {
  if (typeof showEliDialog !== "function") return;
  var t = opts.trophy || {};
  var unlocked = !!opts.unlocked;
  var unlockDate = opts.unlockedAt
    ? new Date(opts.unlockedAt).toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" })
    : null;
  showEliDialog({
    variant: unlocked ? "success" : "neutral",
    tier: "premium",
    icon: t.icon || "🏆",
    title: t.title || t.id || "Trophy",
    body:
      '<p>' + _escTrophy(t.desc || "") + '</p>' +
      (unlocked && unlockDate
        ? '<p class="_eli3_trophy_details_unlocked">✓ Unlocked ' + _escTrophy(unlockDate) + '</p>'
        : '<p class="_eli3_trophy_details_locked">🔒 Locked</p>'),
    secondary: { label: "Close" },
  });
}

jsonTools.init:
function init(eli) {
  if (!eli.events) eli.events = { guard: function (fn) { return fn; }, safeAsync: function (p) { return p; } };
  var bundle = eli.tools._loaded["trophy_gallery"];
  if (!bundle) return;
  var efns = bundle._eliEngineFns || {};
  var vfns = bundle._eliViewFns || {};
  var readUserStats       = efns.readUserStats;
  var computeRankProgress = efns.computeRankProgress;
  var analyze             = efns.analyze;
  var renderSidebarBox    = vfns.renderSidebarBox;
  var renderGallery       = vfns.renderGallery;
  var renderTrophyDetails = vfns.renderTrophyDetails;
  if (!readUserStats || !renderSidebarBox || !renderGallery) {
    eli.log.event("tool", "trophy_gallery_load_failed", {
      hasRead: !!readUserStats, hasSidebar: !!renderSidebarBox, hasGallery: !!renderGallery,
    });
    return;
  }

  // ─── Trophy catalog read ─────────────────────────────────────────
  // Trophies live in IDB store "trophies" (kernel STORE_TROPHIES). The
  // data bundle (__data_trophies) populates this on auto-sync.
  function _readTrophies() {
    if (!eli.storage || typeof eli.storage.getAll !== "function") return Promise.resolve([]);
    return eli.storage.getAll("trophies").then(function (rows) {
      // Filter out metadata rows (ids starting with _).
      return (rows || []).filter(function (r) {
        return r && r.id && String(r.id).charAt(0) !== "_";
      });
    }).catch(function () { return []; });
  }

  // ─── Sidebar slot ────────────────────────────────────────────────
  function _build(opts) {
    var stats = readUserStats();
    var unlocked = stats.unlockedTrophies || [];
    renderSidebarBox({
      mount: opts.mount,
      count: unlocked.length,
      onClick: function () { _openGallery(); },
    });
  }

  if (eli.dashboard && typeof eli.dashboard.registerSidebarSlot === "function") {
    eli.dashboard.registerSidebarSlot("trophy_gallery", _build);
  }

  // ─── Open the gallery overlay ────────────────────────────────────
  function _openGallery() {
    try { if (eli.stats && eli.stats.record) eli.stats.record("appOpenedTrophyGallery"); } catch (e) {}
    try { eli.fsm.transition("rendering"); } catch (e) {}
    Promise.all([
      analyze({}, {}),
      _readTrophies(),
    ]).then(function (r) {
      var result = r[0];
      var trophies = r[1] || [];
      var ui = renderGallery({
        unlocked: result.unlocked,
        rank: result.rank,
        progress: result.progress,
        trophies: trophies,
        onDetails: function (trophyId) {
          var def = trophies.filter(function (t) { return t.id === trophyId; })[0];
          if (!def || !renderTrophyDetails) return;
          var unlocked = (result.unlocked || []).indexOf(trophyId) !== -1;
          var unlockedAt = result.raw && result.raw.unlockedDates && result.raw.unlockedDates[trophyId];
          renderTrophyDetails({
            trophy: def,
            unlocked: unlocked,
            unlockedAt: unlockedAt,
          });
        },
        onClose: function () {
          try { eli.fsm.transition("idle"); } catch (e) {}
        },
        onReset: _confirmReset,
      });
      // Stash so external code can close (e.g. tile_settings dispatch).
      eli._trophyGalleryUi = ui;
    }).catch(function (err) {
      eli.log.event("tool", "trophy_gallery_open_failed", { msg: err && err.message });
      if (typeof showToast === "function") {
        showToast("Trophy gallery failed: " + (err && err.message || "unknown"), "err");
      }
    });
  }

  // ─── Reset confirmation ──────────────────────────────────────────
  // Admin-gated wipe of all stats + trophies. Mirrors v2 reset flow at
  // showTrophyGallery line 238. Requires password if eli.admin exposes
  // a password gate; otherwise plain confirm dialog.
  function _confirmReset() {
    if (typeof showEliDialog !== "function") return;
    var ov = showEliDialog({
      variant: "danger",
      tier: "premium",
      icon: "⚠️",
      title: "Reset Trophies",
      body: 'This will <strong style="color:#ef4444;">permanently erase</strong> ALL trophies, stats, streaks, and rank progress. You cannot undo this.',
      primary: {
        label: "Wipe Data",
        onclick: function () {
          // Best-effort wipe across the three storage locations.
          try { if (eli.compat) eli.compat.lsRemove("eli_user_stats"); } catch (e) {}
          try { if (eli.storage) eli.storage.clearStore("stats").catch(function () {}); } catch (e) {}
          try { if (eli.storage) eli.storage.clearStore("trophies").catch(function () {}); } catch (e) {}
          if (typeof showToast === "function") showToast("Trophies & stats reset.", "ok");
          if (eli._trophyGalleryUi && eli._trophyGalleryUi.close) {
            try { eli._trophyGalleryUi.close(); } catch (e) {}
          }
          // Refresh sidebar so the empty state lands immediately.
          try { if (eli.dashboard && eli.dashboard.refresh) eli.dashboard.refresh(); } catch (e) {}
        },
      },
      secondary: { label: "Cancel" },
    });
    return ov;
  }

  // ─── Channels ────────────────────────────────────────────────────
  eli.register({
    tile: { app_trophy_gallery: function () { _openGallery(); } },
  });

  eli.log.event("tool", "trophy_gallery_initialized", {});
}

